## Code Example
```javascript
// Node.js pseudo-code for validator
const registry = getRegistryFromDynamoDB();
function validateEvent(evt){
  const v = evt.version;
  const rules = registry[v];
  if(!rules) return {ok:false, reason:'unsupported version'};
  // basic field checks per rules
  return {ok:true};
}
```

